import os
import json
import re
from pathlib import Path
from typing import Dict, List, Tuple, Any, Optional

REPO_DIR = os.environ.get('REPO_DIR', '/workspace/metabase')

class AnalyticsVerifier:
    """Verifies analytics event definitions and types."""

    def __init__(self, repo_dir: str):
        self.repo_dir = repo_dir
        self.analytics_file = Path(repo_dir) / 'frontend' / 'src' / 'metabase' / 'lib' / 'analytics.ts'
        self.test_file = Path(repo_dir) / 'frontend' / 'test' / 'metabase' / 'lib' / 'analytics.test.ts'

    def read_file(self, path: Path) -> Optional[str]:
        """Read file content, return None if file does not exist."""
        if not path.exists():
            return None
        try:
            return path.read_text(encoding='utf-8')
        except Exception:
            return None

    def extract_interface_body(self, content: str, interface_name: str) -> Optional[str]:
        """Extract the body of a TypeScript interface definition."""
        # Match: interface InterfaceName { ... }
        pattern = rf'interface\s+{re.escape(interface_name)}\s*\{{'
        match = re.search(pattern, content)
        if not match:
            return None

        start = match.end()
        brace_count = 1
        i = start
        while i < len(content) and brace_count > 0:
            if content[i] == '{':
                brace_count += 1
            elif content[i] == '}':
                brace_count -= 1
            i += 1

        if brace_count == 0:
            return content[start:i-1]
        return None

    def extract_type_body(self, content: str, type_name: str) -> Optional[str]:
        """Extract the body of a TypeScript type definition."""
        # Match: type TypeName = { ... } or type TypeName = { ... };
        pattern = rf'type\s+{re.escape(type_name)}\s*=\s*{{'
        match = re.search(pattern, content)
        if not match:
            return None

        start = match.end()
        brace_count = 1
        i = start
        while i < len(content) and brace_count > 0:
            if content[i] == '{':
                brace_count += 1
            elif content[i] == '}':
                brace_count -= 1
            i += 1

        if brace_count == 0:
            return content[start:i-1]
        return None

    def check_field_in_body(self, body: str, field_name: str) -> bool:
        """Check if a field exists in an interface/type body."""
        if not body:
            return False
        # Match: field_name : type or field_name?: type or field_name;
        pattern = rf'\b{re.escape(field_name)}\s*\??\s*:'
        return bool(re.search(pattern, body))

    def file_exists(self, path: Path) -> bool:
        """Check if file exists."""
        return path.exists()

    def check_analytics_event_interface(self, content: str) -> Tuple[bool, str]:
        """Verify AnalyticsEvent interface structure."""
        body = self.extract_interface_body(content, 'AnalyticsEvent')
        if not body:
            return False, 'AnalyticsEvent interface not found'

        required_fields = ['event_name', 'payload', 'timestamp']
        for field in required_fields:
            if not self.check_field_in_body(body, field):
                return False, f'AnalyticsEvent missing field: {field}'

        # Check field types
        if 'event_name' in body:
            if 'string' not in body.split('event_name')[1].split('\n')[0]:
                # This is lenient; we check presence more than strict type matching
                pass

        return True, 'AnalyticsEvent interface valid'

    def check_dashboard_viewed_event(self, content: str) -> Tuple[bool, str]:
        """Verify dashboard_viewed event definition."""
        # Check for type or interface for dashboard_viewed payload
        type_body = self.extract_type_body(content, 'DashboardViewedPayload')
        if not type_body:
            # Try to find any definition with the required fields
            # Check if fields appear in content related to dashboard_viewed
            if 'dashboard_viewed' not in content:
                return False, 'dashboard_viewed event not defined'
            # Check required fields
            if 'dashboard_id' not in content:
                return False, 'dashboard_viewed missing dashboard_id field'
            if 'view_duration_ms' not in content:
                return False, 'dashboard_viewed missing view_duration_ms field'
            if 'card_count' not in content:
                return False, 'dashboard_viewed missing card_count field'
            return True, 'dashboard_viewed event fields present (lenient check)'

        required_fields = ['dashboard_id', 'view_duration_ms', 'card_count']
        for field in required_fields:
            if not self.check_field_in_body(type_body, field):
                return False, f'DashboardViewedPayload missing field: {field}'

        return True, 'dashboard_viewed event type valid'

    def check_question_saved_event(self, content: str) -> Tuple[bool, str]:
        """Verify question_saved event definition."""
        type_body = self.extract_type_body(content, 'QuestionSavedPayload')
        if not type_body:
            if 'question_saved' not in content:
                return False, 'question_saved event not defined'
            if 'question_id' not in content:
                return False, 'question_saved missing question_id field'
            if 'question_type' not in content:
                return False, 'question_saved missing question_type field'
            if 'database_id' not in content:
                return False, 'question_saved missing database_id field'
            if 'save_duration_ms' not in content:
                return False, 'question_saved missing save_duration_ms field'
            return True, 'question_saved event fields present (lenient check)'

        required_fields = ['question_id', 'question_type', 'database_id', 'save_duration_ms']
        for field in required_fields:
            if not self.check_field_in_body(type_body, field):
                return False, f'QuestionSavedPayload missing field: {field}'

        return True, 'question_saved event type valid'

    def check_filter_applied_event(self, content: str) -> Tuple[bool, str]:
        """Verify filter_applied event definition."""
        type_body = self.extract_type_body(content, 'FilterAppliedPayload')
        if not type_body:
            if 'filter_applied' not in content:
                return False, 'filter_applied event not defined'
            if 'dashboard_id' not in content:
                return False, 'filter_applied missing dashboard_id field'
            if 'filter_type' not in content:
                return False, 'filter_applied missing filter_type field'
            if 'filter_value_count' not in content:
                return False, 'filter_applied missing filter_value_count field'
            return True, 'filter_applied event fields present (lenient check)'

        required_fields = ['dashboard_id', 'filter_type', 'filter_value_count']
        for field in required_fields:
            if not self.check_field_in_body(type_body, field):
                return False, f'FilterAppliedPayload missing field: {field}'

        return True, 'filter_applied event type valid'

    def check_snake_case_naming(self, content: str) -> Tuple[bool, str]:
        """Verify snake_case usage in event and payload field names."""
        # Check for event name strings like 'dashboard_viewed', 'question_saved', 'filter_applied'
        event_names = ['dashboard_viewed', 'question_saved', 'filter_applied']
        found_events = 0
        for event_name in event_names:
            if f"'{event_name}'" in content or f'"{event_name}"' in content or f'`{event_name}`' in content:
                found_events += 1

        if found_events == 0:
            return False, 'No snake_case event names found'

        # Check for required payload field names in snake_case
        payload_fields = [
            'dashboard_id', 'view_duration_ms', 'card_count',
            'question_id', 'question_type', 'database_id', 'save_duration_ms',
            'filter_type', 'filter_value_count'
        ]
        found_fields = 0
        for field in payload_fields:
            if field in content:
                found_fields += 1

        if found_fields < len(payload_fields) / 2:
            return False, f'Insufficient snake_case payload fields found: {found_fields}/{len(payload_fields)}'

        return True, f'snake_case naming verified: {found_events} events, {found_fields} payload fields'

    def check_record_type_in_interface(self, content: str) -> Tuple[bool, str]:
        """Verify payload field uses Record<string, unknown>."""
        body = self.extract_interface_body(content, 'AnalyticsEvent')
        if not body:
            return False, 'AnalyticsEvent interface not found'

        if 'payload' not in body:
            return False, 'payload field not found in AnalyticsEvent'

        # Extract the line with payload
        lines = body.split('\n')
        payload_line = None
        for line in lines:
            if 'payload' in line:
                payload_line = line
                break

        if not payload_line:
            return False, 'payload field definition not found'

        if 'Record<string, unknown>' in payload_line:
            return True, 'payload uses Record<string, unknown>'
        elif 'Record<string, any>' in payload_line:
            return False, 'payload uses Record<string, any> instead of Record<string, unknown>'
        elif 'object' in payload_line or 'Object' in payload_line:
            return False, 'payload uses generic object type instead of Record<string, unknown>'
        else:
            return False, f'payload type unclear: {payload_line.strip()}'

    def check_timestamp_number(self, content: str) -> Tuple[bool, str]:
        """Verify timestamp field is typed as number."""
        body = self.extract_interface_body(content, 'AnalyticsEvent')
        if not body:
            return False, 'AnalyticsEvent interface not found'

        lines = body.split('\n')
        for line in lines:
            if 'timestamp' in line:
                if 'number' in line:
                    return True, 'timestamp field typed as number'
                elif ':' in line:
                    return False, f'timestamp type unclear: {line.strip()}'

        return False, 'timestamp field definition not found'


