def test_no_camel_case_payload_fields():
    """Test that required payload fields use snake_case, not camelCase."""
    verifier = AnalyticsVerifier(REPO_DIR)
    content = verifier.read_file(verifier.analytics_file)
    assert content, 'Failed to read analytics.ts'

    # Check for camelCase variants that should NOT be present
    forbidden_fields = [
        'dashboardId', 'viewDurationMs', 'cardCount',
        'questionId', 'questionType', 'databaseId', 'saveDurationMs',
        'filterType', 'filterValueCount'
    ]

    for field in forbidden_fields:
        # Allow these only if they are in comments or strings, not as payload field definitions
        # Simple check: if field appears in content, verify it's not a type/interface field
        if field in content:
            # Check if it appears as a field definition (colon after it)
            pattern = rf'\b{re.escape(field)}\s*:'
            if re.search(pattern, content):
                assert False, f'Found camelCase field definition: {field}'


